CREATE OR REPLACE FUNCTION zasp_temporal70.body54(o text, w text, e text, r text, worker_value text, lease_value text, input_value bytea, output_value bytea, model_value text, policy_value text, candidate_value jsonb, approval_value text, expires_value timestamp with time zone, audit_value text, correlation_value text)
