  ) x
  WHERE (d.organization_id,d.workspace_id,d.environment_id,d.definition_id)=(scope_o,scope_w,scope_e,scope_d) AND d.deleted_at IS NULL AND d.activation IN('supervised','autonomous') AND d.body->'enabled'='true'::jsonb AND d.body ? 'existing_test'
